            let mut installed = false;
            let candidates: Vec<_> = required.iter().copied().collect();
            for inner in candidates {
                if attempted.contains(&inner) {
                    continue;
                }
                if self.log.lock().expect("log lock").has(&inner)? {
                    required.remove(&inner);
                    continue;
                }
