    pub(super) fn cached_wrapper_id(
        &self,
        mailbox: ConversationId,
        inner: EventId,
    ) -> Option<EventId> {
        let key = hint_key(mailbox, inner);
        let bytes = self
            .opaque_receive_cache
                .expect("wrapper cache lock not poisoned")
                .wrap(self.mailbox, &inner)
