                continue;
            };
            let bytes = outer.ciphertext.len().saturating_add(512);
            if !page.is_empty() && used.saturating_add(bytes) > WRAPPER_PAGE_BYTES {
                break;
            }
            used += bytes;
            page.push(outer);
        }
